-- Phase 3 of the NPC / bestiary work, fifth book: every species Rifts Dimension
-- Book 2: Phase World stats - the five creatures of its Monsters and Animals
-- section (Arboreal Wailers, Kreeghor Bloodhounds, Lesser and Vampire Ugglies,
-- Killer Apes) and the seven NPC races it stats like classes but labels NPC-only
-- (Second Stage Promethean, True Naruni, Royal Kreeghor, Killer Beetles, Worker
-- Ants, Hive Queens, the Dominator) - rows for creatures (migration 074) and their
-- attacks in stat_attacks (owner_kind 'creature').
--
-- One-off data script, run once per environment. NOT a migration.
--
-- NOT HERE: the playable races, which are published classes; the Kreeghor Emperor
-- and the named NPC crew (printed 173-182), who are individuals, for
-- notable_npcs, and are not imported yet.
--
-- A RIFTS BOOK: an M.D.C. creature's pool is its M.D.C. The Second Stage
-- Promethean's book stats are changes to a First Stage Promethean, a published
-- class (first-stage-promethean): each attribute is that class's dice plus the
-- printed change, and its P.P.E. is the First Stage's plus the Second's.
--
-- EXTRACTED by three book-extract-workers, each given the NAMES of its species,
-- every number read off a 200 dpi render - this book is cached from a scan, so its
-- text is OCR. RECONCILED by book-reconcile against the renders, row by row; its
-- corrections are applied. Every row passes creatureFormulaGaps, the grammar the
-- endpoint rolls with. description and natural_abilities are short paraphrases -
-- no sentence is the book's.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-creatures-phase-world.sql
--
-- BY CATEGORY:
--   animal (4): Arboreal Wailers, Kreeghor Bloodhounds, Lesser Ugglies, Killer Apes
--   monster (1): Vampire Ugglies
--   alien (3): Second Stage Promethean, True Naruni R.C.C., Dominator
--   humanoid (1): Royal Kreeghor R.C.C.
--   insectoid (3): Killer Beetles, Worker Ants, Hive Queens

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'arboreal-wailers', 'Arboreal Wailers', 'animal', 'rifts', 0, 'Anarchist (a trained wailer can be Unprincipled)', '{"IQ":"1D4+4","ME":"1D6+8","MA":"1D6+10","PS":"3D6","PP":"3D6+6","PE":"4D6","PB":"2D6","Spd":"4D6"}', NULL, NULL, '1D6x10', '6', NULL, NULL, NULL, NULL, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"dodge":4,"roll":4}', '+4 to strike with ultrasonic howls (conditional, beyond the base +2); +2 to save vs poison and disease; all bonuses are in addition to attribute bonuses.; attacks per melee: 4 hand to hand, or 2 ultrasonic howls, or 1 howl + 2 hand to hand; damage: Claw 1D6 M.D.; Bite 1D4 M.D.', NULL, 'Keen senses; 200 ft nightvision; prehensile tail and toes; expert climbing (80+2D6%) and acrobatics (70+2D4%); emits a mega-damage ultrasonic howl that also disorients and stuns nearby targets.', NULL, NULL, '3 to 5 feet (0.9-1.2 m) tall', '50 to 80 lbs (23-36 kg)', '25 years', 'Forests and jungles', NULL, 'Large M.D.C. predators', NULL, 'A small, tough reptilian primate native to Seljuk, kept as a pet, that unleashes a damaging sonic shriek in self-defense.', 'Rifts Dimension Book 2: Phase World p.109');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'kreeghor-bloodhounds', 'Kreeghor Bloodhounds', 'animal', 'rifts', 0, 'Diabolic (predatory monster)', '{"IQ":"1D4+4","ME":"2D6","MA":"2D6","PS":"4D6+6","PP":"4D6+6","PE":"5D6","PB":"1D6","Spd":"6D6+32"}', NULL, NULL, '1D4x100', '20', NULL, NULL, NULL, 12, '{"attacks":5,"initiative":3,"strike":3,"parry":3,"dodge":3,"roll":2}', 'All bonuses are in addition to attribute bonuses.; damage: Bite 4D6 M.D.; Claws 1D6 M.D. + P.S. damage', NULL, 'Rapid healing (1D6x10 M.D.C. per hour); bionic-level hearing and sight; 1000 ft nightvision; powerful leaper (20 ft standing, doubled running); strong swimmer, climber, and prowler; nearly impossible to sneak up on.', NULL, NULL, '4 feet (1.2 m) tall at the shoulder, 7 feet (2.1 m) long', '200 lbs (91 kg)', '16 years in the wild, 26 if domesticated', 'Any - adapts equally to jungle, forest, mountain, desert, and cities', NULL, 'Intelligent beings and other large predators', NULL, 'A bio-engineered, quadrupedal predator resembling a monstrous kreeghor, bred by the Splugorth as a devastating hunting and guard animal.', 'Rifts Dimension Book 2: Phase World p.110-111');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'lesser-ugglies', 'Lesser Ugglies', 'animal', 'rifts', 0, 'Anarchist scavengers (spacers often call them diabolic)', '{"IQ":"1D6","ME":"2D6","MA":"2D6","PS":"2D6","PP":"3D6","PE":"3D6","PB":"1D4","Spd":"3D6+6"}', NULL, NULL, '1', '25', NULL, 'Printed as "Hit Points: 100 S.D.C./Hit Points (1 M.D.C. point)"; the M.D.C. rating of 1 is used here since this is an M.D.C.-setting book, and the combined 100 S.D.C./Hit Points figure is the stated equivalent as printed. Can be damaged by S.D.C. weapons/attacks despite being M.D.C.', NULL, 6, '{"attacks":1,"strike":1,"dodge":1,"roll":1}', 'Impervious to poisons, drugs, and disease. Horror Factor rises to 12 in a pack of more than 10 individuals.; attacks per melee: 1 (4 if in a swarm of 10 or more); strike: +1 (+6 in a swarm); damage: Acid secretion: 1D4x10 S.D.C. (S.D.C. structures) or 1 M.D. (mega-damage structures); swarm of 10+: 1D4x100 S.D.C. or 1D4 M.D. per melee round', NULL, 'Survives vacuum without breathing; digests almost any organic or plastic material with acidic secretions; skilled climber and prowler; squeezes through tight gaps; typically nests in walls, crawlspaces, and sewers.', NULL, NULL, '2 to 4 feet (0.6-1.2 m) tall, tentacles reach 4 to 6 feet (printed metric as 1.2 to 1.8 feet)', NULL, '6 months', 'Ocean vessels, spaceships, space stations, sewers, alleys, basements, garbage dumps, and filthy urban areas (printed as Habit)', NULL, NULL, NULL, 'A tiny, tentacled scavenger that infests starships, dissolving cargo and hull materials with corrosive digestive enzymes wherever it spreads.', 'Rifts Dimension Book 2: Phase World p.111');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'vampire-ugglies', 'Vampire Ugglies', 'monster', 'rifts', 0, 'Diabolic', '{"IQ":"2D6","ME":"2D6+6","MA":"2D6+6","PS":"3D6","PP":"4D6","PE":"4D6+3","PB":"1D4","Spd":"4D6"}', NULL, NULL, '1D4x10', '1D6', NULL, 'Printed as "M.D.C. by Location: 1D4x10 M.D.C." but only one whole-body value is given, with no per-location breakdown. Unlike lesser ugglies, immune to S.D.C. attacks.', NULL, 10, '{"attacks":3,"strike":4,"dodge":4}', 'Solitary predator; avoids direct contact with prey and fights only when cornered.; damage: Bite 1D6 M.D.; lashing tentacle 3D6 S.D.C.', NULL, 'Secretly drains a chosen victim of P.P.E., I.S.P., then P.E. once daily via a failed psionic save, weakening skills and combat ability before causing coma and eventual death if unchecked.', NULL, 'None, aside from its life-drain ability; detectable by psionic sense evil or presence sense.', NULL, NULL, 'Unknown', 'Same as the lesser ugglies: spaceships, space stations, and cities', NULL, NULL, NULL, 'A rare, disguised variant of the lesser ugglie that secretly drains a victim of mystical and life energy until death.', 'Rifts Dimension Book 2: Phase World p.112');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'killer-apes', 'Killer Apes', 'animal', 'rifts', 0, 'Diabolic predators', '{"IQ":"2D6","ME":"3D6","MA":"2D6","PS":"4D6+20","PP":"2D6+10","PE":"2D6+10","PB":"2D4","Spd":"4D6"}', NULL, NULL, '1D4x100', '2D6', NULL, 'P.S. and P.E. are noted in the attribute line as supernatural strength and endurance.', NULL, 12, '{"attacks":4,"initiative":1,"strike":4,"parry":5,"dodge":5,"roll":2}', '+3 to save vs magic and psionics; all bonuses are in addition to attribute bonuses. Horror Factor rises to 17 when one or two characters face five or more apes.; damage: Claws 1D6 M.D. + supernatural P.S.; Bite 2D6 M.D.', NULL, 'Keen night vision and smell; tracks by scent and sight; strong climber, swimmer, and prowler; bio-regenerates 3D6 M.D.C. per hour; cunning enough to use tools, open doors, and wield weapons, but untamable.', NULL, NULL, '5 to 6 feet (1.5-1.8 m) tall', NULL, '50 years; twice as long in captivity', 'Jungles and forests', NULL, NULL, NULL, 'A savage, hairy, gorilla-like carnivore inhabiting ancient ruins, strong enough to rip through mega-damage armor with its bare claws.', 'Rifts Dimension Book 2: Phase World p.112-113');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'second-stage-promethean', 'Second Stage Promethean', 'alien', 'rifts', 0, 'Unknown (between principled and aberrant, depending on situation)', '{"IQ":"3D6+12","ME":"3D4+12","MA":"3D4+12","PS":"4D6+1D6+16","PP":"3D6-2","PE":"3D6+13","PB":"2D4-1","Spd":"3D6-1D6"}', NULL, NULL, '4D6x100', '3D6x10+2D6x10', NULL, 'Attributes are a First Stage Promethean''s dice plus the printed changes; P.P.E. is the First Stage''s 3D6x10 plus 2D6x10. I.S.P. is triple what it had as a First Stage (which prints none of its own). Average level 1D6+3, on the dragon experience table from level 10.', NULL, 14, '{"initiative":1}', '+6 save vs magic, +6 save vs psionics, +6 save vs horror factor, all in addition to attribute and skill bonuses. Combat is described only as First Stage abilities at level 10, no further combat gains regardless of age or level; no numeric strike/parry/dodge printed.', 'R.C.C. Skills: in addition to the skills of a 10th-level First Stage promethean, select six additional other skills.', 'Does not breathe; immune to radiation, heat, cold, gas, disease; darkvision. Permanently phased: no damage from S.D.C. weapons, quarter from other attacks, half from magic/psionics. Teleports 1,000 miles, shifts dimensions, senses dimensional anomalies within a mile, phases along ley lines.', 'Only spells learned as a First Stage promethean', 'All sensitive, physical and healing psionic powers, plus 4 super-psionic powers, learning one more every level after the first', '15 to 30 feet (4.6 to 9 m) tall', '4 to 6 tons (3600 to 5400 kg)', 'Unknown; presumably thousands of years, possibly true immortals', 'Phase World, the city of Center; rarely intervenes in the wider Megaverse', 'Zurvan (Persian god of time); Brahma (ruler of the Indian Pantheon); assorted gods and supernatural beings on good terms with them', 'Splugorth (hostile, but every direct attack has failed)', NULL, 'A rare, immensely powerful NPC-only stage of promethean development: giant, rock-bodied, phased beings who oversee the city of Center on Phase World and rarely intervene beyond it.', 'Rifts Dimension Book 2: Phase World p.31');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'true-naruni', 'True Naruni R.C.C.', 'alien', 'rifts', 0, 'Any, but most are aberrant or miscreant', '{"IQ":"2D6+13","ME":"3D6","MA":"3D6","PS":"3D6","PP":"3D6","PE":"3D6+6","PB":"1D6","Spd":"3D6"}', NULL, NULL, '2D4x10', '1D4x10', NULL, NULL, NULL, 11, NULL, '+6 save vs horror factor, +3 save vs disease, in addition to attribute/skill bonuses. Combat: Hand to Hand: Basic only; damage is based on P.S. with no printed number. Vulnerability: takes double damage from rune and holy weapons.', 'R.C.C. Skills: Basic and Advanced Math (+20%), six languages of choice (+15%), Lore: Demons and Monsters (+10%), Basic Electronics (+15%), Mechanical Engineering (+15%), Weapons Engineer (+20%), Intelligence (+10%), Concealment (+10%), W.P. any two, Hand to Hand: Basic, never better than basic. Plus select 12 R.C.C. related skills, at least two electrical and two mechanical, and six secondary skills.', 'Supernatural strength and endurance; very long-lived; heals 1D6x10 M.D.C. every 8 hours. Three nose-tentacles used for eating and breathing, tipped with tiny fanged mouths. Presence unsettles psychics and sensitives.', NULL, 'All sensitive powers, plus automatic mind block, bio-manipulation and empathic transmission; considered master psionics', '6 to 8 feet (1.8 to 2.4 m) tall', '300 lbs (136 kg)', '1,000+ years', 'Behind the scenes of Naruni Enterprises across the Three Galaxies; avoid public appearances', 'Uteni (public front-men for Naruni Enterprises)', NULL, NULL, 'The secretive, supernatural true owners of Naruni Enterprises: hideous, tentacle-faced, hippo-built beings who never appear publicly and let the Uteni serve as their public face.', 'Rifts Dimension Book 2: Phase World p.48-49');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'royal-kreeghor', 'Royal Kreeghor R.C.C.', 'humanoid', 'rifts', 0, 'Any evil', '{"IQ":"3D6+3","ME":"2D6+12","MA":"3D6+3","PS":"5D6+12","PP":"3D6+6","PE":"4D6+6","PB":"2D4","Spd":"4D6+12"}', NULL, NULL, '1D6x100+250', '5D6x10', '3D6x10+ME', 'M.D.C. also grows +1D4x10 per level of experience beyond the printed base. I.S.P. also gains +2D6 per level of experience beyond the printed base. P.S. is supernatural strength.', NULL, 14, '{"initiative":1,"strike":1,"parry":2,"dodge":2,"roll":1,"pull":1}', '+1 save vs magic, +6 save vs horror factor, in addition to attribute/skill bonuses. Combat is described as equivalent to Hand to Hand: Assassin. Vulnerabilities: magic, magic weapons and holy items inflict double damage; rune weapons inflict triple damage; weapons from a Millennium Tree inflict ten times damage.', 'R.C.C. Skills: Literate in Trade Five 98%, two other languages (+20%), Basic Radio (+10%), Computer Operation (+5%), Power Armor: Elite, Fighter Combat: Elite, Pilot: two of choice (+15%), Weapon Systems (+15%), W.P. any two, Hand to Hand: Assassin. Plus select 8 R.C.C. related skills and 4 secondary skills.', 'See the invisible, immune to mind control, bio-regenerates 1D6x10 M.D.C. per minute, and regrows severed limbs within 1D6 hours. 30% larger than common kreeghor, with dark gray or black hide.', 'None normally; mystically knows six spells at first level, chosen from levels 1-3, and gains a new spell every level after that, always at or below the current experience level; cannot learn or purchase spells normally', 'Considered master psionics: starts with 3 powers from healing/sensitive/physical plus 1 super-psionic power, mind-melter limits; +2 more powers at levels 2 and 3, +1 more at levels 5, 9 and 13', '8 to 10 feet (2.4 to 3.0 m) fully erect, but tends to crouch', '300-500 lbs (136 to 227 kg)', '1,000+ years', 'Transgalactic Empire; Imperial Homeworld, about 2 million, and scattered across the galaxy as military commanders, up to 10 million total', 'the kreeghor race, in awe of them, will give their lives for them', NULL, NULL, 'Royal Kreeghor are supernatural kreeghor nobles bred for war, commanding legions of the Transgalactic Empire with psionic and magical power ordinary kreeghor lack.', 'Rifts Dimension Book 2: Phase World p.74-76');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'killer-beetles', 'Killer Beetles', 'insectoid', 'rifts', 0, 'Considered evil', '{"IQ":"2D4","ME":"3D6","MA":"2D4","PS":"4D6+20","PP":"4D6","PE":"5D6","PB":"2D4","Spd":"5D6"}', NULL, NULL, '1D6x100+150', '4D6', '2D6x10', 'M.D.C. by location: Legs (8) 20 each, Centauroid Torso 4D6x10+50, Arms (4) 60 each, Head 90 (all small/hard to hit, called shot at -4 to strike). I.S.P. is 2D6x10 plus 10 per level of experience.', NULL, 12, '{"attacks":5,"initiative":2,"strike":3,"parry":5,"dodge":5,"roll":3,"pull":3}', '+3 save vs magic, +6 save vs horror factor (plus attribute bonuses); +1 to strike at level 4; +1 to parry/dodge at levels 3 and 7; +1 attack at levels 3 and 7; add 2D6 M.D. to all hand to hand damage; superhuman strength and endurance; takes double damage from psionic attacks.', 'Limited skills; track by scent 60% plus 3% per level, swimming 80%, movement: zero gravity 75%.', 'Multi-spectrum vision with radar (200 ft); regenerates lost limbs/M.D.C. 1D4x10 per 8-hour rest; psionically recognizes own hive and attacks all others; fires psionic energy bolts at range.', NULL, 'See aura, see the invisible, sense magic, mind-block auto-defense; hive-only telepathy at no I.S.P. cost; special energy bolt 5D6 M.D., range 1000 ft (305 m), 8 I.S.P. per bolt.', 'Ten feet (3.0 m) tall and ten feet (3.0 m) long.', NULL, '20 years.', 'Interior of a Star Hive.', 'Other killer beetles; worker ants; the controlling Hive', 'Any non-hive-recognized being, including hive-spawn of other hives', NULL, 'Centauroid, four-armed insectoid soldier defending Star Hives; slices through mega-damage armor with taloned claws and mandibles, and fires psionic bolts.', 'Rifts Dimension Book 2: Phase World p.91-92');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'worker-ants', 'Worker Ants', 'insectoid', 'rifts', 0, 'Considered to be evil', '{"IQ":"1D6","ME":"1D6+6","MA":"1D6+6","PS":"2D6+12","PP":"1D6+12","PE":"1D6+12","PB":"1D4","Spd":"1D6+12"}', NULL, NULL, '2D6x10', '1D6', NULL, NULL, NULL, 9, '{"attacks":3,"strike":2,"parry":3,"dodge":3}', '+2 to strike, +3 to parry and dodge, +6 save vs horror factor (plus attribute bonuses); +1 attack at levels 5 and 10; takes double damage from psionic attacks.', NULL, 'Heals 4D6 M.D.C. per 8-hour rest; psionically recognizes and communicates only with its own hive members, attacking all others on sight.', NULL, 'None, other than the ability to communicate psionically with hive members.', 'Six feet (1.8 m) long and 4 feet (1.2 m) tall.', '180 lbs (82 kg).', '10 years.', 'Within a Star Hive.', 'Termite engineers (supervisors); other worker ants; killer beetles', 'Attackers of the Star Hive', NULL, 'Mindless ant-like hive workers built for repairs, food storage, and defending the Star Hive as expendable soldiers with oversized mandibles.', 'Rifts Dimension Book 2: Phase World p.94');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'hive-queens', 'Hive Queens', 'insectoid', 'rifts', 0, 'Any evil', '{"IQ":"2D6+14","ME":"3D6+10","MA":"3D6+8","PS":"3D6+20","PP":"3D6","PE":"4D6+10","PB":"1D6","Spd":"1D6"}', NULL, NULL, '1D6x1000', '1D4x10', '3D6x100', NULL, NULL, 15, '{"attacks":5,"strike":5,"parry":5,"dodge":1}', '+5 to strike and parry, +1 dodge, +4 save vs magic, +4 save vs psionics, +10 save vs horror factor; no listed vulnerabilities, highly resistant to psionic attacks.', 'Little use for normal skills; telepathically knows all languages; demon and monster lore 70% plus 5% per level; wilderness survival, land navigation, swim, and basic math all at 92%.', 'Controls and senses through the entire hive via psionic link, seeing and speaking through any member''s eyes; regenerates 1D4x10 M.D.C. per minute; fires long-range mind bolts.', NULL, 'Knows all sensitive powers plus bio-manipulation, empathic transmission, mentally possess others, mind block auto-defense, mind wipe, telekinesis, and telekinetic force field; mind bolt 1D4x10 M.D., range 500 feet (152 m).', '30 feet (9.1 m) long and 12 feet (3.7 m) tall.', '12 tons (10,900 kg).', '50,000 years.', 'Deep within a Star Hive, guarded by workers and beetles.', 'Worker ants; killer beetles; all members of its own Star Hive', 'Outsiders and explorers who contact or attack the Star Hive', NULL, 'Enormous, ancient worm-like insectoid intelligence at a Star Hive''s core; slow-moving but psionically dominant, controlling and perceiving through the whole hive.', 'Rifts Dimension Book 2: Phase World p.95');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'dominator', 'Dominator', 'alien', 'rifts', 0, 'Any evil', '{"IQ":"2D6+18","ME":"2D6+18","MA":"2D6+18","PS":"4D6+36","PP":"3D6+6","PE":"3D6+18","PB":"2D4","Spd":"1D6x10"}', NULL, NULL, '2D4x1000', '2D6x10', NULL, NULL, NULL, 15, '{"initiative":1,"strike":1,"parry":2,"dodge":2}', '+1 initiative, +1 strike, +2 parry/dodge, +10 save vs horror factor (plus attribute and skill bonuses); supernatural attributes; combat equivalent to Hand to Hand: Assassin; hand to hand damage varies with P.S.; takes double damage from magic attacks and weapons. Weapons: Starsplitter (3D6x10 M.D. melee plus hand to hand damage, or 4D6x10 M.D. bolt at 2000 ft/610 m), Nova Gun (2D6x10 or 1D4x100 M.D. settings), Collector Bubbles (500 M.D.C. field, 1/10 damage from energy, double from magic), plus 1D6 other unique weapons/vehicles; Body Armor 1000 M.D.C. body, 500 M.D.C. limbs and head.', 'Select 24 skills with a +15% bonus (no skills needed to operate their computer-run starships); select four W.P.s and Hand to Hand: Assassin.', 'Superior ancient technology and senses; regenerates 4D6 M.D.C. per melee round; effectively immortal; fights at Hand to Hand: Assassin level; strikes with supernatural strength.', NULL, 'Natural mind block (no I.S.P. cost); highly resistant to psionic powers (per M.E. attribute).', '30 feet tall (9.1 m).', '10 tons (9070 kg).', 'Unknown, presumably indefinite.', 'Roams the Three Galaxies aboard personal, planetoid-sized starships.', 'Occasionally alien intelligences, evil gods, demons, and fallen knights (tend to be loners)', 'Cosmo-Knights; the Splugorth', NULL, 'Giant, bleach-white-skinned humanoid survivor of an ancient god-like race, armed with superior lost technology; often rules as a tyrant or lone conqueror.', 'Rifts Dimension Book 2: Phase World p.96');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
  ('creature', 'arboreal-wailers', 'Claw', '1D6 M.D.', 1, 'melee', NULL, 0),
  ('creature', 'arboreal-wailers', 'Bite', '1D4 M.D.', 1, 'melee', NULL, 1),
  ('creature', 'arboreal-wailers', 'Ultrasonic Howl', '2D6 M.D.', 1, '100 ft (30.5 m), one specific target', 'Also causes loss of initiative, loss of one melee attack, and -10% on skills within a 50 ft (15.2 m) radius', 2),
  ('creature', 'kreeghor-bloodhounds', 'Bite', '4D6 M.D.', 1, 'melee', NULL, 0),
  ('creature', 'kreeghor-bloodhounds', 'Claws', '1D6 M.D. + P.S. damage', 1, 'melee', NULL, 1),
  ('creature', 'lesser-ugglies', 'Acid Secretion (lone)', '1D4x10 S.D.C. or 1 M.D.', 0, 'touch/melee', '1 M.D. point vs mega-damage structures', 0),
  ('creature', 'lesser-ugglies', 'Acid Secretion (swarm of 10+)', '1D4x100 S.D.C. or 1D4 M.D.', 0, 'touch/melee', 'per melee round, swarm only', 1),
  ('creature', 'vampire-ugglies', 'Bite', '1D6 M.D.', 1, 'melee', NULL, 0),
